{  "explanation": "This is the classic base rate fallacy, solved with Bayes' theorem. Out of 1,000 people, only about 10 are sick, and 9 of them test positive — but 99 of the 990 healthy people also (falsely) test positive. So of the 108 positive tests, only 9 are actually sick: 9/108 ≈ 8.3%. Even a 90%-accurate test gives a surprising result because the disease is rare; drag the sliders to see how prevalence, sensitivity, and specificity change the answer.",  "manimCode": "// ---- Title ----
const title = new Text({ text: 'The Base Rate Fallacy', color: WHITE, fontSize: 38 });
title.moveTo([-0.9, 3.5, 0]);
await scene.play(new Write(title));

// ---- Divider ----
const divider = new Line({ start: [-0.45, 2.9, 0], end: [-0.45, -1.6, 0], color: GRAY });
divider.setOpacity(0.4);
scene.add(divider);

// ---- Population grid: 1,000 dots ----
const COLS = 40, ROWS = 25, N = 1000;
const spacing = 0.13;
const cx = -3.35, cy = 0.4;
const dots = [];
for (let r = 0; r < ROWS; r++) {
  for (let c = 0; c < COLS; c++) {
    const x = cx + (c - (COLS - 1) / 2) * spacing;
    const y = cy + ((ROWS - 1) / 2 - r) * spacing;
    const d = new Dot({ point: [x, y, 0], radius: 0.05, color: GRAY });
    dots.push(d);
    scene.add(d);
  }
}

const caption = new Text({ text: 'each dot = 1 person (1,000 total)', color: GRAY, fontSize: 20 });
caption.moveTo([cx, cy - 1.85, 0]);
scene.add(caption);

// ---- Deterministic shuffle so colored dots spread out ----
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(12345);
const orderIdx = [];
for (let i = 0; i < N; i++) orderIdx.push(i);
for (let i = N - 1; i > 0; i--) {
  const j = Math.floor(rng() * (i + 1));
  const tmp = orderIdx[i]; orderIdx[i] = orderIdx[j]; orderIdx[j] = tmp;
}

// ---- Parameters (percent) ----
let prevPct = 1, sensPct = 90, specPct = 90;

// ---- Stats panel (Text is immutable: remove & recreate on update) ----
let statMobs = [];
function setStats(items) {
  for (const m of statMobs) scene.remove(m);
  statMobs = [];
  for (const it of items) {
    const t = new Text({ text: it.s, color: it.c, fontSize: it.f });
    t.moveTo([2.75, it.y, 0]);
    scene.add(t);
    statMobs.push(t);
  }
}

function updateViz() {
  const sick = Math.max(1, Math.round(prevPct * 10));
  const healthy = N - sick;
  const tp = Math.round(sick * sensPct / 100);
  const fp = Math.round(healthy * (1 - specPct / 100));
  const totalPos = tp + fp;
  const pct = totalPos > 0 ? (100 * tp / totalPos) : 0;

  for (let i = 0; i < N; i++) {
    const d = dots[orderIdx[i]];
    if (i < tp) { d.setColor(RED); d.setOpacity(1); }           // sick, test +
    else if (i < sick) { d.setColor(MAROON); d.setOpacity(0.9); } // sick, test -
    else if (i < sick + fp) { d.setColor(YELLOW); d.setOpacity(1); } // healthy, test +
    else { d.setColor(GRAY); d.setOpacity(0.22); }              // healthy, test -
  }

  setStats([
    { s: 'Out of 1,000 people:', c: WHITE, f: 26, y: 2.55 },
    { s: sick + ' sick  •  ' + healthy + ' healthy', c: GRAY, f: 22, y: 2.0 },
    { s: 'Tested positive: ' + totalPos, c: WHITE, f: 24, y: 1.3 },
    { s: tp + ' sick (true positives)', c: RED, f: 22, y: 0.72 },
    { s: fp + ' healthy (false positives)', c: YELLOW, f: 22, y: 0.22 },
    { s: 'P(sick | +) \u2248 ' + pct.toFixed(1) + '%', c: GOLD, f: 40, y: -0.6 },
    { s: '= ' + tp + ' of ' + totalPos + ' positive tests', c: GOLD, f: 20, y: -1.3 },
  ]);
}

// ---- Bayes formula ----
const formula = new MathTex({ latex: 'P(\\text{sick}\\,|\\,+)=\\frac{P(+\\,|\\,\\text{sick})\\,P(\\text{sick})}{P(+\\,|\\,\\text{sick})\\,P(\\text{sick})+P(+\\,|\\,\\text{healthy})\\,P(\\text{healthy})}' });
await formula.waitForRender();
formula.scale(0.5);
formula.moveTo([-2.2, -3.35, 0]);
scene.add(formula);

updateViz();

// ---- Interactive controls ----
const controls = new Controls(scene, { position: 'bottom-right', width: 250 });
controls.addSlider({ label: 'Prevalence (%)', min: 0.1, max: 20, value: 1, step: 0.1, onChange: (v) => { prevPct = v; updateViz(); } });
controls.addSlider({ label: 'Sensitivity (%)', min: 50, max: 100, value: 90, step: 1, onChange: (v) => { sensPct = v; updateViz(); } });
controls.addSlider({ label: 'Specificity (%)', min: 50, max: 100, value: 90, step: 1, onChange: (v) => { specPct = v; updateViz(); } });

await scene.wait(999999);"}

